{"atom_id":"atom-0047","atom_type":"requirement","canonical_summary":"Goal completion is not a worker judgment. The runtime must certify that all required inputs were inventoried, required work was represented or dispositioned, validations ran, acceptance criteria are satisfied, unresolved items are explicit, and no required source/target areas are unaccounted for.","compile_disposition":"create_new_planunit","compile_notes":"Compiled to live canonical Plans PlanUnits; governance seal completed.","compiled_at_utc":"2026-06-16T05:06:00Z","compiled_output_plan_unit_ids":["GRS-012","CV-286","SP-214"],"created_at_utc":"2026-06-16T04:00:00Z","exact_tokens":["completion certification","inventoried","represented","dispositioned","acceptance criteria","unaccounted for"],"gui_classification_reason":"Backend/orchestration or product architecture; not GUI/UI or visual implementation work.","gui_related":false,"lane":"completion","ledger_id":"pldg-20260616-001-goal-runtime-system","negative_constraints":["Do not treat task-count completion or token presence as sufficient."],"owner_hints":["Plans/Goal_Runtime_System.md"],"plan_compile_targets":[],"schema_id":"pm.bootstrap_design_atom.v1","source_refs":["chat:goal-mode-design-thread","repo:Plans/ledgers/v2/README.md","repo:Concepts/PMConcept.html"],"status":"compiled_to_plan","superseded_by":[],"supersedes":[],"title":"Evidence-based completion certification","updated_at_utc":"2026-06-16T20:30:00Z"}
