def run_git(args, text=True):
    return subprocess.check_output(["git", *args], cwd=ROOT, text=text)


def load_json(path):
    with Path(path).open() as f:
        return json.load(f)


def load_jsonl(path):
    rows = []
    with Path(path).open() as f:
        for line in f:
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows


def write_json(path, data):
    with (AUDIT_DIR / path).open("w") as f:
